<?php require 'config.php';require_login();$title='Attendance';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$pdo->prepare('INSERT INTO attendance(employee_id,attendance_date,status) VALUES(?,?,?) ON DUPLICATE KEY UPDATE status=VALUES(status)')->execute([(int)$_POST['employee_id'],$_POST['attendance_date'],$_POST['status']]);flash('Attendance saved.');go('attendance.php');}
$emps=$pdo->query('SELECT id,name FROM employees ORDER BY name')->fetchAll();$rows=$pdo->query('SELECT a.*,e.name FROM attendance a JOIN employees e ON e.id=a.employee_id ORDER BY a.attendance_date DESC,a.id DESC LIMIT 50')->fetchAll();require 'partials/header.php';?>
<div class="pagehead"><div><div class="eyebrow">TIME & ATTENDANCE</div><h1>Attendance</h1><p class="sub">Record and review daily employee attendance.</p></div></div>
<div class="card"><h2>Mark attendance</h2><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><div class="formgrid" style="margin-top:15px"><div class="field"><label>Employee</label><select name="employee_id" required><?php foreach($emps as $e):?><option value="<?=$e['id']?>"><?=h($e['name'])?></option><?php endforeach?></select></div><div class="field"><label>Date</label><input type="date" name="attendance_date" value="<?=date('Y-m-d')?>" required></div><div class="field"><label>Status</label><select name="status"><option>Present</option><option>Absent</option><option>Leave</option></select></div></div><div class="actions"><button class="btn">Save attendance</button></div></form></div>
<div class="card"><div class="cardhead"><h2>Recent attendance</h2></div><div class="tablewrap"><table><thead><tr><th>Employee</th><th>Date</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=h($r['name'])?></td><td><?=h($r['attendance_date'])?></td><td><span class="badge <?=$r['status']==='Absent'?'red':($r['status']==='Leave'?'warn':'')?>"><?=h($r['status'])?></span></td></tr><?php endforeach?><?php if(!$rows):?><tr><td colspan="3" class="empty">No attendance records yet.</td></tr><?php endif?></tbody></table></div></div><?php require 'partials/footer.php';?>
